INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Zugriffskontrollen nur für sensible Systeme nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Systeme sollten geschützt werden"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz sinnvoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Zugriffskontrollen?', 3, '[{"text": "Unbefugten Zugriff verhindern", "correct": true, "because": "Schützt Daten und Systeme"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mechanismen gehören zu Zugriffskontrollen?', 5, '[{"text": "Passwörter", "correct": true, "because": "Authentifizierungsmethode"}, {"text": "Rollen", "correct": true, "because": "Bestimmen Berechtigungen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Farbschema", "correct": false, "because": "Nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Authentifizierung bestätigt Identität. b) Autorisierung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Autorisierung ist essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung von Zugriffskontrollen?', 4, '[{"text": "Authentifizierungsmethoden", "correct": false, "because": "Kern der Kontrolle"}, {"text": "Berechtigungsstufen", "correct": false, "because": "Definieren Zugriff"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Zugriffskontrollen auch physische Mittel umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Schlüsselkarten"}, {"text": "Nein", "correct": false, "because": "Nicht nur digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel nutze ich für Authentifizierung?', 3, '[{"text": "Zwei-Faktor-Authentifizierung", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein direkter Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze sichern Zugriffskontrollen?', 5, '[{"text": "Rollenbasierte Zugriffskontrolle", "correct": true, "because": "Regelt Berechtigungen"}, {"text": "Biometrie", "correct": true, "because": "Authentifiziert Nutzer"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Zugriffskontrollen schützen Daten. b) Passwörter allein reichen immer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Passwörter oft unsicher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Zugriffskontrollen?', 4, '[{"text": "Passwortrichtlinien", "correct": false, "because": "Sichern Authentifizierung"}, {"text": "Rollenmanagement", "correct": false, "because": "Definiert Zugriff"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Authentifizierung dasselbe wie Autorisierung?', 2, '[{"text": "Nein", "correct": true, "because": "Identität vs. Berechtigung"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen Zugriffskontrollen?', 4, '[{"text": "Single Sign-On", "correct": true, "because": "Vereinfacht Authentifizierung"}, {"text": "RBAC", "correct": true, "because": "Rollenbasierte Autorisierung"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Zugriffskontrollen nur technische Mittel brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Regeln"}, {"text": "Ja", "correct": false, "because": "Prozesse spielen mit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Zugriffskontrollen?', 3, '[{"text": "Starke Authentifizierung", "correct": true, "because": "Sichert Identität"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Sekundär"}, {"text": "Grafisches Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rollen definieren Berechtigungen. b) Passwörter sind immer sicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Passwörter können schwach sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken verbessern Zugriffskontrollen?', 5, '[{"text": "MFA", "correct": true, "because": "Mehrfaktor-Authentifizierung"}, {"text": "ACLs", "correct": true, "because": "Zugriffssteuerungslisten"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Zugriffskontrollen unwichtig?', 3, '[{"text": "Benutzerrollen", "correct": false, "because": "Definieren Zugriff"}, {"text": "Authentifizierung", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Schriftarten", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Zugriffskontrollen nur für IT-Systeme?', 3, '[{"text": "Nein", "correct": true, "because": "Auch physische Kontrollen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Zugriffskontrollen regelmäßig überprüft werden sollten?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheit gewährleisten"}, {"text": "Nein", "correct": false, "because": "Regelmäßige Audits nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wähle ich für starke Zugriffskontrollen?', 4, '[{"text": "Biometrische Authentifizierung", "correct": true, "because": "Hohe Sicherheit"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Irrelevant"}, {"text": "Grafische Effekte", "correct": false, "because": "Kein Schutzfaktor"}]');
